 #[NoAdminRequired] public function saveReport(int $projectId,string $reportDate,string $title,?string $description=null,array $entryIds=[],array $materialEntryIds=[]):RedirectResponse{$this->permissions->assertProjectAccess($projectId);$project=$this->one('re_erp_projects',$projectId);if(!$project)throw new \InvalidArgumentException('Projekt nicht gefunden.');$title=trim($title);if($title==='')throw new \InvalidArgumentException('Titel fehlt.');$number=$this->numbers->next('report');$path=$this->folders->ensureReportFolder((string)$project['folder_path'],$number,$title);$id=$this->insert('re_erp_reports',['customer_id'=>$project['customer_id'],'project_id'=>$projectId,'report_no'=>$number,'report_date'=>$reportDate,'title'=>$title,'description'=>$description,'status'=>'Entwurf','folder_path'=>$path,'created_by'=>$this->uid(),'created_at'=>date('Y-m-d H:i:s'),'updated_at'=>date('Y-m-d H:i:s')]);foreach($entryIds as $raw){$entryId=(int)$raw;if($entryId<=0)continue;$entry=$this->timeEntry($entryId);if(!$entry||$entry['imported_to_report_id']!==null||(int)$entry['project_id']!==$projectId)continue;$this->insert('re_erp_report_hours',['report_id'=>$id,'user_id'=>$entry['user_id'],'hours'=>$entry['hours'],'activity'=>$entry['activity'],'work_date'=>$entry['work_date']??null,'source_entry_id'=>$entryId]);foreach($this->workdayMaterials($entryId) as $material)$this->importWorkdayMaterialToReport($id,$material);$this->update('re_erp_workday_entries',$entryId,['imported_to_report_id'=>$id]);}foreach($materialEntryIds as $rawMaterialId){$materialId=(int)$rawMaterialId;if($materialId<=0)continue;$material=$this->workdayMaterialForProject($materialId,$projectId);if(!$material)continue;$this->importWorkdayMaterialToReport($id,$material);}$this->activities->record('report',$id,'created','Rapport erstellt',$number.' · '.$title,(int)$project['customer_id'],$projectId);$this->writeReportSnapshot($id);return $this->go('reinhardterp.module.reportDetail',['id'=>$id]);}
