 #[NoAdminRequired,NoCSRFRequired] public function reportPdf(int $id):DataDownloadResponse{
  $report=$this->one('re_erp_reports',$id);if(!$report)throw new \OCP\AppFramework\Http\NotFoundResponse();
  $this->permissions->assertProjectAccess((int)$report['project_id']);
  $project=$this->one('re_erp_projects',(int)$report['project_id']);
  $customer=$project?$this->one('re_erp_customers',(int)$project['customer_id']):null;
  $logo=$this->folders->companyLogo();
  $pdf=$this->pdf->createReport($report,$project,$customer,$this->reportHours($id),$this->where('re_erp_report_items','report_id',$id,'id'),$logo,$this->reportPhotoFiles($id),$this->companyData());
  $name=preg_replace('/[^A-Za-z0-9._-]+/','_',trim((string)($report['report_no']??'Rapport'))).'_Rapport.pdf';
