 #[NoAdminRequired,NoCSRFRequired] public function settings():TemplateResponse{$this->permissions->assert('settings');$logo=$this->folders->companyLogo();return new TemplateResponse($this->appName,'settings',['uid'=>$this->uid(),'logoPath'=>$logo['path']??null,'logoDataUri'=>$logo?'data:'.$logo['mime'].';base64,'.base64_encode($logo['content']):null,'company'=>$this->companyData(),'hourlyRates'=>$this->hourlyRates(),'calendars'=>$this->integration->availableCalendars(),'selectedCalendarKey'=>$this->integration->selectedCalendarKey(),'selectedCalendarName'=>$this->integration->selectedCalendarName()]);}
 #[NoAdminRequired] public function saveSettings():RedirectResponse{
  $this->permissions->assert('settings');
  foreach(['name','owner','street','zip','city','country','phone','email','website','taxNo','vatId','registerCourt','registerNo'] as $key){
   $value=trim((string)$this->request->getParam('company_'.$key,''));
   $this->config->setAppValue($this->appName,'company_'.$key,$value);
  }
  $upload=$this->request->getUploadedFile('companyLogo');
  if($upload&&(($upload['error']??UPLOAD_ERR_NO_FILE)!==UPLOAD_ERR_NO_FILE)){
   if(empty($upload['tmp_name'])||!is_uploaded_file($upload['tmp_name']))throw new \InvalidArgumentException('Die Logo-Datei konnte nicht gelesen werden.');
   if(($upload['error']??UPLOAD_ERR_OK)!==UPLOAD_ERR_OK)throw new \InvalidArgumentException('Das Logo konnte nicht hochgeladen werden.');
   if(($upload['size']??0)>5*1024*1024)throw new \InvalidArgumentException('Das Logo darf maximal 5 MB groß sein.');
   $info=@getimagesize($upload['tmp_name']);$mime=$info['mime']??'';$ext=$mime==='image/png'?'png':($mime==='image/jpeg'?'jpg':'');
   if($ext==='')throw new \InvalidArgumentException('Erlaubt sind PNG und JPG.');
   $content=file_get_contents($upload['tmp_name']);if($content===false)throw new \RuntimeException('Das Logo konnte nicht gelesen werden.');
   $this->folders->saveCompanyLogo($content,$ext);
  }
  return $this->go('reinhardterp.module.settings');
 }
 private function companyData():array{
  $out=[];foreach(['name','owner','street','zip','city','country','phone','email','website','taxNo','vatId','registerCourt','registerNo'] as $key)$out[$key]=$this->config->getAppValue($this->appName,'company_'.$key,'');
  return $out;
 }

 #[NoAdminRequired] public function saveHourlyRate(?int $id,string $name,string $code,float $salesRate,float $costRate=0,?string $validFrom=null,int $active=1):RedirectResponse{$this->permissions->assert('settings');$name=trim($name);$code=strtoupper(trim($code));if($name===''||$code==='')throw new \InvalidArgumentException('Bezeichnung und Kürzel sind erforderlich.');if($salesRate<0||$costRate<0)throw new \InvalidArgumentException('Stundensätze dürfen nicht negativ sein.');$data=['name'=>$name,'code'=>$code,'sales_rate'=>$salesRate,'cost_rate'=>$costRate>0?$costRate:null,'valid_from'=>$validFrom?:null,'active'=>$active===1?1:0];if($id&&$id>0)$this->update('re_erp_hourly_rates',$id,$data);else{$data['created_at']=date('Y-m-d H:i:s');$this->insert('re_erp_hourly_rates',$data);}return $this->go('reinhardterp.module.settings');}
 private function writeReportSnapshot(int $id):void{
  $r=$this->one('re_erp_reports',$id);if(!$r)return;
  $p=$this->one('re_erp_projects',(int)$r['project_id']);if(!$p)return;
  $c=$this->one('re_erp_customers',(int)$p['customer_id']);
  $projectPath=trim((string)($p['folder_path']??''),'/');
  if($projectPath===''){
   if(!$c)return;
   $customerPath=trim((string)($c['folder_path']??''),'/');
   if($customerPath===''){$customerPath=$this->folders->ensureCustomerFolder((string)($c['customer_no']??''),(string)($c['name']??'Kunde'));$this->update('re_erp_customers',(int)$c['id'],['folder_path'=>$customerPath]);}
   $projectPath=$this->folders->ensureProjectFolder($customerPath,(string)($p['project_no']??''),(string)($p['title']??'Projekt'));
   $this->update('re_erp_projects',(int)$p['id'],['folder_path'=>$projectPath]);
  }
  $folderPath=$this->folders->ensureReportFolder($projectPath,(string)$r['report_no'],(string)$r['title']);
  $hours=$this->where('re_erp_report_hours','report_id',$id,'id');
  $items=$this->where('re_erp_report_items','report_id',$id,'id');
  $logo=$this->folders->companyLogo();
  $photos=$this->reportPhotoFiles($id);
  $pdf=$this->pdf->createReport($r,$p,$c,$hours,$items,$logo,$photos,$this->companyData());
  $pdfName=(string)$r['report_no'].'_Rapport.pdf';
  $pdfPath=$this->folders->write($folderPath,$pdfName,$pdf);
  $rootPath=$this->folders->ensureReportRoot($projectPath);
  $visibleName=(string)$r['report_no'].'_'.(string)$r['title'].'.pdf';
  $this->folders->write($rootPath,$visibleName,$pdf);
  $this->update('re_erp_reports',$id,['folder_path'=>$folderPath,'print_path'=>$pdfPath,'updated_at'=>(string)($r['updated_at']??date('Y-m-d H:i:s'))]);
 }


 private function reportPhotoFiles(int $reportId):array{
  $photos=[];
  foreach($this->where('re_erp_report_files','report_id',$reportId,'id') as $row){
   $path=trim((string)($row['path']??''),'/');if($path==='')continue;
   try{$file=$this->folders->readFile($path);}catch(\Throwable){continue;}
   $mime=strtolower((string)($file['mime']??''));if(!str_starts_with($mime,'image/'))continue;
   $photos[]=['path'=>$path,'name'=>(string)($file['name']??basename($path)),'mime'=>$mime,'content'=>(string)($file['content']??''),'created_at'=>(string)($row['created_at']??''),'category'=>$this->reportPhotoCategory($path)];
  }
  return $photos;
 }
 private function reportPhotoCategory(string $path):string{
  foreach(['Vorher','Nachher','Montage','Schaden','Abnahme','Sonstige'] as $category)if(str_contains('/'.$path.'/','/'.$category.'/'))return $category;
  return 'Sonstige';
 }



 private function reportRows(bool $archived=false):array{$qb=$this->db->getQueryBuilder();$qb->select('r.*','p.project_no','p.title AS project_title','c.name AS customer_name')->from('re_erp_reports','r')->leftJoin('r','re_erp_projects','p',$qb->expr()->eq('p.id','r.project_id'))->leftJoin('p','re_erp_customers','c',$qb->expr()->eq('c.id','p.customer_id'))->where($qb->expr()->eq('r.archived',$qb->createNamedParameter($archived?1:0)))->orderBy('r.report_date','DESC')->addOrderBy('r.id','DESC');$rows=$qb->executeQuery()->fetchAllAssociative();return array_values(array_filter($rows,fn(array $r):bool=>$this->permissions->canAccessProject((int)$r['project_id'])));}
 private function reportCountByArchive(bool $archived):int{return count($this->reportRows($archived));}
 private function usersArray():array{$users=[];$this->userManager->callForSeenUsers(function($user)use(&$users){$users[]=['uid'=>$user->getUID(),'displayName'=>$user->getDisplayName(),'isAdmin'=>$this->groupManager->isAdmin($user->getUID())];});return $users;}
 private function activeErpUsers():array{$all=$this->usersArray();$out=[];foreach($all as $u){if($this->permissions->isEnabled($u['uid']))$out[]=$u;}usort($out,fn($a,$b)=>strcasecmp($a['displayName'],$b['displayName']));return $out;}
 private function workdayRows(string $from,string $to):array{$qb=$this->db->getQueryBuilder();$qb->select('w.id','w.user_id','w.entered_by','w.work_date','w.start_time','w.end_time','w.break_minutes','w.notes','e.id AS entry_id','e.activity','e.hours','e.project_id','e.imported_to_report_id','p.project_no','p.title')->from('re_erp_workdays','w')->leftJoin('w','re_erp_workday_entries','e',$qb->expr()->eq('e.workday_id','w.id'))->leftJoin('e','re_erp_projects','p',$qb->expr()->eq('p.id','e.project_id'))->where($qb->expr()->gte('w.work_date',$qb->createNamedParameter($from)))->andWhere($qb->expr()->lte('w.work_date',$qb->createNamedParameter($to)))->orderBy('w.work_date','DESC')->addOrderBy('w.start_time','DESC')->setMaxResults(500);$rows=$qb->executeQuery()->fetchAllAssociative();foreach($rows as &$row)$row['materials']=!empty($row['entry_id'])?$this->workdayMaterials((int)$row['entry_id']):[];unset($row);return $rows;}
 private function weeklySummary(string $from,string $to):array{$rows=$this->workdayRows($from,$to);$users=[];$days=[];$total=0.0;foreach($rows as $r){$h=(float)($r['hours']??0);$uid=(string)$r['user_id'];$date=(string)$r['work_date'];$users[$uid]=($users[$uid]??0)+$h;$days[$date]=($days[$date]??0)+$h;$total+=$h;}ksort($days);arsort($users);return ['total'=>$total,'users'=>$users,'days'=>$days];}
 private function materialRows():array{$qb=$this->db->getQueryBuilder();$qb->select('m.*','g.name AS group_name','s.name AS supplier_name')->from('re_erp_materials','m')->leftJoin('m','re_erp_material_groups','g',$qb->expr()->eq('g.id','m.material_group_id'))->leftJoin('m','re_erp_suppliers','s',$qb->expr()->eq('s.id','m.supplier_id'))->orderBy('m.name','ASC')->setMaxResults(5000);return $qb->executeQuery()->fetchAllAssociative();}
 private function activeMaterials():array{$qb=$this->db->getQueryBuilder();$qb->select('*')->from('re_erp_materials')->where($qb->expr()->eq('active',$qb->createNamedParameter(1)))->orderBy('name','ASC')->setMaxResults(2000);return $qb->executeQuery()->fetchAllAssociative();}
 private function saveWorkdayMaterials(?int $entryId,?int $timerId,array $materialIds,array $descriptions,array $quantities,array $units,array $unitPrices):void{$count=max(count($materialIds),count($descriptions),count($quantities));for($i=0;$i<$count;$i++){$materialId=(int)($materialIds[$i]??0);$description=trim((string)($descriptions[$i]??''));$quantity=(float)($quantities[$i]??0);$unit=trim((string)($units[$i]??''));$unitPrice=max(0,(float)($unitPrices[$i]??0));if($quantity<=0||($materialId<=0&&$description===''))continue;$material=$materialId>0?$this->one('re_erp_materials',$materialId):null;if($description===''&&$material)$description=(string)$material['name'];if($unit===''&&$material)$unit=(string)($material['unit']??'');if($unitPrice<=0&&$material)$unitPrice=(float)($material['sale_price']??$material['price']??0);$this->insert('re_erp_workday_materials',['workday_entry_id'=>$entryId,'timer_id'=>$timerId,'material_id'=>$materialId?:null,'description'=>$description,'quantity'=>$quantity,'unit'=>$unit?:null,'unit_price'=>$unitPrice,'total_price'=>round($quantity*$unitPrice,2),'imported_to_report_id'=>null,'invoice_id'=>null,'created_by'=>$this->uid(),'created_at'=>date('Y-m-d H:i:s')]);}}
 private function workdayMaterials(int $entryId):array{$qb=$this->db->getQueryBuilder();$qb->select('*')->from('re_erp_workday_materials')->where($qb->expr()->eq('workday_entry_id',$qb->createNamedParameter($entryId)))->orderBy('id','ASC');return $qb->executeQuery()->fetchAllAssociative();}
 private function availableProjectMaterials(int $projectId):array{$qb=$this->db->getQueryBuilder();$qb->select('m.*','e.activity','w.work_date','w.user_id')->from('re_erp_workday_materials','m')->innerJoin('m','re_erp_workday_entries','e',$qb->expr()->eq('e.id','m.workday_entry_id'))->innerJoin('e','re_erp_workdays','w',$qb->expr()->eq('w.id','e.workday_id'))->where($qb->expr()->eq('e.project_id',$qb->createNamedParameter($projectId)))->andWhere($qb->expr()->orX($qb->expr()->isNull('m.imported_to_report_id'),$qb->expr()->eq('m.imported_to_report_id',$qb->createNamedParameter(0))))->orderBy('w.work_date','ASC')->addOrderBy('m.id','ASC');$rows=$qb->executeQuery()->fetchAllAssociative();foreach($rows as &$row){$user=$this->userManager->get((string)$row['user_id']);$row['display_name']=$user?->getDisplayName()??(string)$row['user_id'];}unset($row);return $rows;}
 private function workdayMaterialForProject(int $materialEntryId,int $projectId):?array{$qb=$this->db->getQueryBuilder();$qb->select('m.*')->from('re_erp_workday_materials','m')->innerJoin('m','re_erp_workday_entries','e',$qb->expr()->eq('e.id','m.workday_entry_id'))->where($qb->expr()->eq('m.id',$qb->createNamedParameter($materialEntryId)))->andWhere($qb->expr()->eq('e.project_id',$qb->createNamedParameter($projectId)));$row=$qb->executeQuery()->fetchAssociative();return $row?:null;}
 private function importWorkdayMaterialToReport(int $reportId,array $material):void{if(!empty($material['imported_to_report_id']))return;$materialId=(int)($material['id']??0);if($materialId<=0)return;$this->insert('re_erp_report_items',['report_id'=>$reportId,'material_id'=>!empty($material['material_id'])?(int)$material['material_id']:null,'description'=>(string)$material['description'],'quantity'=>$material['quantity'],'unit'=>$material['unit']?:null,'notes'=>'Aus Zeiterfassung übernommen','unit_price'=>$material['unit_price'],'total_price'=>$material['total_price'],'source_workday_material_id'=>$materialId]);$this->update('re_erp_workday_materials',$materialId,['imported_to_report_id'=>$reportId]);}
 private function activeTimers():array{$qb=$this->db->getQueryBuilder();$qb->select('t.*','p.project_no','p.title')->from('re_erp_time_timers','t')->leftJoin('t','re_erp_projects','p',$qb->expr()->eq('p.id','t.project_id'))->where($qb->expr()->in('t.status',[$qb->createNamedParameter('running'),$qb->createNamedParameter('paused')]))->orderBy('t.started_at','ASC');return $qb->executeQuery()->fetchAllAssociative();}
 private function normalizeWeekStart(?string $week):string{$ts=$week&&preg_match('/^\\d{4}-\\d{2}-\\d{2}$/',$week)?strtotime($week):time();$day=(int)date('N',$ts);return date('Y-m-d',strtotime('-'.($day-1).' days',$ts));}
 private function timeEvaluationRows(string $from,string $to,?int $customerId,?int $projectId,?string $userId,string $billingStatus):array{$qb=$this->db->getQueryBuilder();$qb->select('e.id','e.customer_id','e.project_id','e.activity','e.hours','e.imported_to_report_id','e.billing_status','e.billing_rate','e.billing_reference','e.billed_at','e.billed_by','w.user_id','w.work_date','w.start_time','w.end_time','w.break_minutes','w.entered_by','p.project_no','p.title AS project_title','p.special_hourly_rate','c.customer_no','c.name AS customer_name','ur.individual_hourly_rate','hr.sales_rate AS group_sales_rate','hr.name AS hourly_rate_name')->from('re_erp_workday_entries','e')->innerJoin('e','re_erp_workdays','w',$qb->expr()->eq('w.id','e.workday_id'))->leftJoin('e','re_erp_projects','p',$qb->expr()->eq('p.id','e.project_id'))->leftJoin('e','re_erp_customers','c',$qb->expr()->eq('c.id','e.customer_id'))->leftJoin('w','re_erp_user_roles','ur',$qb->expr()->eq('ur.user_id','w.user_id'))->leftJoin('ur','re_erp_hourly_rates','hr',$qb->expr()->eq('hr.id','ur.hourly_rate_id'))->where($qb->expr()->gte('w.work_date',$qb->createNamedParameter($from)))->andWhere($qb->expr()->lte('w.work_date',$qb->createNamedParameter($to)));if($customerId)$qb->andWhere($qb->expr()->eq('e.customer_id',$qb->createNamedParameter($customerId)));if($projectId)$qb->andWhere($qb->expr()->eq('e.project_id',$qb->createNamedParameter($projectId)));if($userId!==null&&$userId!=='')$qb->andWhere($qb->expr()->eq('w.user_id',$qb->createNamedParameter($userId)));if($billingStatus!=='all')$qb->andWhere($qb->expr()->eq('e.billing_status',$qb->createNamedParameter($billingStatus)));$qb->orderBy('c.name','ASC')->addOrderBy('p.project_no','ASC')->addOrderBy('w.work_date','ASC')->setMaxResults(2000);return $qb->executeQuery()->fetchAllAssociative();}
 private function availableTimeEntries(int $projectId):array{$qb=$this->db->getQueryBuilder();$qb->select('e.id','e.project_id','e.activity','e.hours','w.user_id','w.work_date')->from('re_erp_workday_entries','e')->innerJoin('e','re_erp_workdays','w',$qb->expr()->eq('w.id','e.workday_id'))->where($qb->expr()->eq('e.project_id',$qb->createNamedParameter($projectId)))->andWhere($qb->expr()->orX($qb->expr()->isNull('e.imported_to_report_id'),$qb->expr()->eq('e.imported_to_report_id',$qb->createNamedParameter(0))))->orderBy('w.work_date','ASC')->addOrderBy('e.id','ASC');$rows=$qb->executeQuery()->fetchAllAssociative();foreach($rows as &$row){$user=$this->userManager->get((string)$row['user_id']);$row['display_name']=$user?->getDisplayName()??(string)$row['user_id'];}unset($row);return $rows;}
